-- ═══ EXÉCUTÉ le 06/10/2026 par Claude (via l app connectée, compte admin) : 29 lignes insérées, vérifiées. ═══
-- Programme d'OCTOBRE 2026 de WAKA UP, encodé d'après leur calendrier
-- (image envoyée par Mag le 05/10/2026). Texte en base64 : le presse-papier vers
-- l'éditeur SQL abîme les accents. pour_qui = 'femmes' DÈS l'encodage (voir waka-femmes.sql).
--
-- ATTENTION AUX LIEUX. Le calendrier ne dit pas où se passent : le vernissage (2),
-- le foot en salle (mardis), les ateliers Karibu (14), le festival (25), le tricot
-- @ Crazy (29) et l'escalade (30). Ces lignes portent « Lieu à confirmer » plutôt
-- qu'une adresse inventée.
-- Les lundis portent le lotus : « moment bien-être sur rendez-vous, réservation par
-- message » — encodé comme une ligne à part, sans heure.
delete from public.activites where asso = convert_from(decode('V0FLQSBVUA==','base64'),'UTF8') and jour >= '2026-10-01' and jour <= '2026-10-31';
select jour, titre, debut, fin, lieu, pour_qui from public.activites where asso = convert_from(decode('V0FLQSBVUA==','base64'),'UTF8') and jour >= '2026-10-01' order by jour, debut;
